// A self-signed certificate for localhost (RSA 2048, valid 100 years), imported into a throwaway keychain.
import Foundation
import Security

enum TestIdentity {
  static let p12 = ""

  nonisolated(unsafe) static let identity: SecIdentity = {
    let path = FileManager.default.temporaryDirectory.appendingPathComponent("fakeftp-\(UUID().uuidString).keychain").path
    var keychain: SecKeychain?
    precondition(SecKeychainCreate(path, 4, "test", false, nil, &keychain) == errSecSuccess)
    var items: CFArray?
    let options: [String: Any] = [kSecImportExportPassphrase as String: "test", kSecImportExportKeychain as String: keychain!]
    precondition(SecPKCS12Import(Data(base64Encoded: p12)! as CFData, options as CFDictionary, &items) == errSecSuccess)
    let first = (items as! [[String: Any]])[0]
    return first[kSecImportItemIdentity as String] as! SecIdentity
  }()
}
